-- Quiz system upgrade: recategorize the original seed quiz under the new
-- 6-category taxonomy shared with Podcasts, then seed 14 more quizzes (5
-- questions each) so there are 15 quizzes total, 2-3 per category.

update quizzes set category = 'starting_a_business' where id = '00000000-0000-0000-0000-000000000001';

insert into quizzes (id, title, description, category, min_level, question_count, time_limit_seconds, xp_reward, is_active)
