  ('00000000-0000-0000-0000-000000000005', 'Social Media for Business', 'Using social platforms to grow an audience.', 'marketing_branding', 3, 5, 120, 45, true),
  ('00000000-0000-0000-0000-000000000006', 'Building a Brand', 'What makes a brand memorable and trustworthy.', 'marketing_branding', 6, 5, 120, 50, true),
  ('00000000-0000-0000-0000-000000000007', 'Budgeting Basics', 'Managing money in and money out.', 'money_finance', 2, 5, 120, 40, true),
  ('00000000-0000-0000-0000-000000000008', 'Understanding Profit & Loss', 'How businesses know if they''re actually making money.', 'money_finance', 5, 5, 120, 45, true),
  ('00000000-0000-0000-0000-000000000009', 'Leadership Fundamentals', 'What makes someone worth following.', 'leadership_teams', 3, 5, 120, 40, true),
